#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    string a, b;
    cin >> a >> b;
    reverse(a.begin(), a.end());
    reverse(b.begin(), b.end());
    string result = "";
    int carry = 0;
    int maxLen = max(a.length(), b.length());
    for (int i = 0; i < maxLen; i++) {
        int da = (i < a.length()) ? (a[i] - '0') : 0;
        int db = (i < b.length()) ? (b[i] - '0') : 0;
        int sum = da + db + carry;
        result += (char)('0' + sum % 10);
        carry = sum / 10;
    }
    if (carry) result += '1';
    reverse(result.begin(), result.end());
    cout << result << endl;
    return 0;
}

#include <iostream>
#include <string>
#include <stack>
using namespace std;

int main() {
    string s;
    cin >> s;
    stack<char> st;
    for (int i = 0; i < s.length(); i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else {
            if (st.empty()) { cout << "No" << endl; return 0; }
            char top = st.top();
            if ((c == ')' && top == '(') || (c == ']' && top == '[') || (c == '}' && top == '{')) {
                st.pop();
            } else {
                cout << "No" << endl; return 0;
            }
        }
    }
    cout << (st.empty() ? "Yes" : "No") << endl;
    return 0;
}
